mapper.select:
SELECT UID, UserName, LoginPwd, Gender, Email, Phone, Status, CreateTime, Remark, Avatar
FROM users
WHERE UID = #{uid}

SELECT u.UID, u.UserName, u.Gender, u.Email, u.Phone, u.Status, u.CreateTime, u.Remark, u.Avatar, GROUP_CONCAT(r.RoleName ORDER BY r.RID SEPARATOR ',') AS roleNames FROM users u LEFT JOIN userroles ur ON u.UID = ur.UID LEFT JOIN roles r ON ur.RID = r.RID
AND ur.RID = #{role}
AND (u.UserName LIKE CONCAT('%', #{keyword}, '%') OR u.Email LIKE CONCAT('%', #{keyword}, '%') OR u.Phone LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY u.UID, u.UserName, u.Gender, u.Email, u.Phone, u.Status, u.CreateTime, u.Remark, u.Avatar ORDER BY u.UID DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT u.UID) FROM users u LEFT JOIN userroles ur ON u.UID = ur.UID LEFT JOIN roles r ON ur.RID = r.RID
AND ur.RID = #{role}
AND (u.UserName LIKE CONCAT('%', #{keyword}, '%') OR u.Email LIKE CONCAT('%', #{keyword}, '%') OR u.Phone LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
